from __future__ import annotations

import sys
import tomllib
from pathlib import Path

import pytest

# the app has no package install: import it from its folder
APP_DIR = Path(__file__).resolve().parents[3] / "services" / "ui"
sys.path.insert(0, str(APP_DIR))

from ui import config as config_module  # noqa: E402
from ui.config import Config, config, set_config  # noqa: E402
from ui.session import BUILTIN_NAMES, Session  # noqa: E402
from ui.tool_forms import ToolRequest  # noqa: E402
from ui.widgets import form_by_key, form_for, widget_of  # noqa: E402


@pytest.fixture(autouse=True)
def config_file(monkeypatch: pytest.MonkeyPatch, tmp_path: Path) -> Path:
    """A settings file of the test's own: the real services/ui/config.toml is never touched."""
    file = tmp_path / "config.toml"
    monkeypatch.setattr(config_module, "CONFIG_FILE", file)
    return file


@pytest.fixture
def picture(tmp_path: Path) -> Path:
    file = tmp_path / "forest.png"
    file.write_bytes(b"png")
    return file


def test_a_setting_is_its_default_until_set(config_file: Path) -> None:
    assert not config_file.exists()
    assert config.background == config_module.OMARCHY_BACKGROUND
    setting = config.settings()[0]
    assert (setting.name, setting.type, setting.is_default) == ("background", "Path", True)
    assert setting.about.startswith("The picture the window shows when no panel is open.")
    assert config.stored() == {"background": "", "allow_ai": True}  # an on/off setting: its value in use


def test_setting_one_writes_the_file_and_resetting_takes_it_out(config_file: Path, picture: Path) -> None:
    result = config.set_background(str(picture))
    assert config.background == picture
    assert result.background == str(picture)
    assert tomllib.loads(config_file.read_text(encoding="utf-8")) == {"background": str(picture)}
    assert config.settings()[0].is_default is False
    # None, as an empty input: back to the default, and the key leaves the file
    set_config(background=None)
    assert config.background == config_module.OMARCHY_BACKGROUND
    assert tomllib.loads(config_file.read_text(encoding="utf-8")) == {}


def test_a_path_under_home_is_kept_with_a_tilde(monkeypatch: pytest.MonkeyPatch, tmp_path: Path) -> None:
    monkeypatch.setattr(Path, "home", lambda: tmp_path)
    (tmp_path / "pics").mkdir()
    (tmp_path / "pics" / "x.png").write_bytes(b"png")
    monkeypatch.setenv("HOME", str(tmp_path))
    config.set_background("~/pics/x.png")
    assert 'background = "~/pics/x.png"' in config_module.CONFIG_FILE.read_text(encoding="utf-8")
    assert config.background == tmp_path / "pics" / "x.png"


def test_a_bad_value_is_refused_and_nothing_changes(config_file: Path, tmp_path: Path) -> None:
    with pytest.raises(ValueError, match="background: no such file"):
        config.set_background(str(tmp_path / "nope.png"))
    assert not config_file.exists()
    with pytest.raises(ValueError, match="not a setting: colour"):
        set_config(colour="red")


def test_a_hand_edit_applies_on_the_next_use(config_file: Path, picture: Path) -> None:
    assert config.background == config_module.OMARCHY_BACKGROUND
    config_file.write_text(f'background = "{picture}"\n', encoding="utf-8")
    assert config.background == picture  # no restart, nothing kept from before


def test_a_broken_file_leaves_the_defaults_and_says_why(config_file: Path) -> None:
    config_file.write_text("background = [unclosed\n", encoding="utf-8")
    assert config.background == config_module.OMARCHY_BACKGROUND
    assert "can't be read" in config.problem
    config_file.write_text('background = "/no/such/file.png"\ncolour = "red"\n', encoding="utf-8")
    assert config.background == config_module.OMARCHY_BACKGROUND
    assert "background: no such file" in config.problem
    assert "colour: not a setting" in config.problem


def test_every_property_is_a_setting_with_nothing_else_written() -> None:
    # what "add the property, nothing else" rests on: the inputs, the form, set_<name>
    properties = [name for name, member in vars(Config).items() if isinstance(member, property)]
    form = form_by_key("set_config")
    assert form is not None
    assert list(form.schema["properties"]) == properties
    for name in properties:
        assert form.schema["properties"][name]["description"]
        assert callable(getattr(config, f"set_{name}"))
    with pytest.raises(AttributeError):
        config.set_nothing  # noqa: B018  # not a setting


def test_the_widget_starts_with_what_is_set_and_runs_the_same(picture: Path) -> None:
    config.set_background(str(picture))
    widget = widget_of("config")
    blank = widget.blank(Session())
    assert isinstance(blank, ToolRequest)
    assert blank.inputs == {"background": str(picture), "allow_ai": True}
    # run untouched: nothing changes
    result, used = widget.form.run(widget.form.texts(blank.inputs))
    assert config.background == picture
    assert used == {"background": picture, "allow_ai": True}
    assert "allow_ai" not in tomllib.loads(config_module.CONFIG_FILE.read_text(encoding="utf-8"))  # on: not set
    assert form_for(result) is widget.form  # the result keeps the form
    # an emptied input: back to the default
    widget.form.run({"background": ""})
    assert config.settings()[0].is_default


def test_config_is_there_in_a_python_cell() -> None:
    assert "config" in BUILTIN_NAMES
    assert Session().namespace["config"] is config
